    propertyBuilder.setMediaType(text);
    propertyBuilder.setSubType(plain);
    SimpleMailboxMessage<TestId> original = new SimpleMailboxMessage<TestId>(new Date(), MESSAGE_CONTENT.length(), BODY_START_OCTET, new SharedByteArrayInputStream(MESSAGE_CONTENT.getBytes(MESSAGE_CHARSET)), new Flags(), propertyBuilder, TEST_ID);
