@Test
public void shouldAllowWorkingDefinition() {
    Bad400 bad400 = new Bad400();
    SpyFilter spyFilter = new SpyFilter();
    LambdaFilter anotherFilter = (req, resp, chain) -> chain.doFilter(req, resp);
    Configuration testee = Configuration.builder().port(2000).serve("/abc").with(Ok200.class).serve("/def").with(bad400).filter("/123").with(CoolFilter.class).and(anotherFilter).only().filter("/456").with(spyFilter).only().build();
    assertThat(testee.getPort()).isPresent().contains(2000);
    assertThat(testee.getMappings()).hasSize(2).containsEntry("/abc", Ok200.class).containsEntry("/def", bad400);
    assertThat(testee.getFilters().asMap()).hasSize(2).containsEntry("/123", ImmutableList.of(CoolFilter.class, anotherFilter)).containsEntry("/456", ImmutableList.of(spyFilter));
}

