    assertNotNull(entries);
    assertEquals(1, entries.length);
    assertEquals(1, pop3Client.getState());
    Reader r = pop3Client.retrieveMessage(entries[0].number);
    assertNotNull(r);
    r.close();
    mailboxManager.deleteMailbox(mailboxPath, session);
}

